CREATE TABLE users (id TEXT PRIMARY KEY, username TEXT NOT NULL UNIQUE, passphrase_hash TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'administrator', created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE bootstrap_tokens (id INTEGER PRIMARY KEY CHECK (id = 1), token_hash TEXT NOT NULL, expires_at TEXT NOT NULL, used_at TEXT);
CREATE TABLE sessions (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), token_hash TEXT NOT NULL UNIQUE, csrf_hash TEXT NOT NULL, expires_at TEXT NOT NULL, created_at TEXT NOT NULL, last_seen_at TEXT NOT NULL, revoked_at TEXT);
CREATE INDEX sessions_active ON sessions(token_hash, expires_at);
CREATE TABLE api_tokens (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), token_hash TEXT NOT NULL UNIQUE, label TEXT NOT NULL, created_at TEXT NOT NULL, expires_at TEXT, revoked_at TEXT);
CREATE TABLE machines (id TEXT PRIMARY KEY, name TEXT NOT NULL, mode TEXT NOT NULL, status TEXT NOT NULL, last_heartbeat_at TEXT, os TEXT NOT NULL, architecture TEXT NOT NULL, hostname TEXT NOT NULL, docker_version TEXT, compose_version TEXT, agent_version TEXT NOT NULL, capabilities_json TEXT NOT NULL DEFAULT '{}', resources_json TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE applications (id TEXT PRIMARY KEY, slug TEXT NOT NULL UNIQUE, name TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', source_path TEXT NOT NULL DEFAULT '', active_machine_id TEXT REFERENCES machines(id), status TEXT NOT NULL DEFAULT 'draft', created_at TEXT NOT NULL, updated_at TEXT NOT NULL, archived_at TEXT);
CREATE TABLE manifest_revisions (id TEXT PRIMARY KEY, app_id TEXT NOT NULL REFERENCES applications(id), content_json TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE services (id TEXT PRIMARY KEY, app_id TEXT NOT NULL REFERENCES applications(id), name TEXT NOT NULL, kind TEXT NOT NULL DEFAULT 'generic', required_for_health INTEGER NOT NULL DEFAULT 1, internal_port INTEGER, health_spec_json TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL, UNIQUE(app_id, name));
CREATE TABLE releases (id TEXT PRIMARY KEY, app_id TEXT NOT NULL REFERENCES applications(id), source_commit_sha TEXT NOT NULL DEFAULT '', source_branch TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'ready', metadata_json TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL);
CREATE TABLE deployments (id TEXT PRIMARY KEY, app_id TEXT NOT NULL REFERENCES applications(id), release_id TEXT REFERENCES releases(id), machine_id TEXT REFERENCES machines(id), status TEXT NOT NULL, started_at TEXT, finished_at TEXT, failure_code TEXT, failure_summary TEXT);
CREATE TABLE jobs (id TEXT PRIMARY KEY, type TEXT NOT NULL, resource_type TEXT NOT NULL, resource_id TEXT NOT NULL, machine_id TEXT REFERENCES machines(id), status TEXT NOT NULL, phase TEXT NOT NULL, progress_percent INTEGER NOT NULL DEFAULT 0, attempt INTEGER NOT NULL DEFAULT 0, idempotency_key TEXT, requested_by TEXT, input_json TEXT NOT NULL DEFAULT '{}', checkpoint_json TEXT NOT NULL DEFAULT '{}', error_code TEXT, error_detail TEXT, created_at TEXT NOT NULL, started_at TEXT, updated_at TEXT NOT NULL, finished_at TEXT);
CREATE UNIQUE INDEX jobs_idempotency ON jobs(resource_type, resource_id, type, idempotency_key) WHERE idempotency_key IS NOT NULL;
CREATE UNIQUE INDEX one_active_app_mutation ON jobs(resource_id) WHERE resource_type = 'application' AND status IN ('queued','assigned','running','waiting_external','waiting_user');
CREATE TABLE job_events (id INTEGER PRIMARY KEY AUTOINCREMENT, job_id TEXT NOT NULL REFERENCES jobs(id), sequence INTEGER NOT NULL, timestamp TEXT NOT NULL, level TEXT NOT NULL, phase TEXT NOT NULL, code TEXT NOT NULL, message TEXT NOT NULL, metadata_json TEXT NOT NULL DEFAULT '{}', UNIQUE(job_id, sequence));
CREATE TABLE routes (id TEXT PRIMARY KEY, app_id TEXT NOT NULL REFERENCES applications(id), machine_id TEXT REFERENCES machines(id), hostname TEXT NOT NULL, path_prefix TEXT NOT NULL DEFAULT '/', service_id TEXT REFERENCES services(id), target_port INTEGER, tls_mode TEXT NOT NULL DEFAULT 'none', status TEXT NOT NULL DEFAULT 'unconfigured', created_at TEXT NOT NULL);
CREATE TABLE audit_events (id INTEGER PRIMARY KEY AUTOINCREMENT, actor_id TEXT, action TEXT NOT NULL, resource_type TEXT NOT NULL, resource_id TEXT NOT NULL, metadata_json TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL);
